// Map data files (generated by the scripts in tools/).

export interface MapRegion {
  name: string // display name, e.g. "Narmadapuram"
  d: string // SVG path data
  lx: number // label point x (inside the region)
  ly: number // label point y
  alt: string[] // extra accepted spellings, lowercase, e.g. ["hoshangabad"]
  short?: string // shorter label for the map, when the name is long
  small?: boolean // too small to click on screen: the game draws a click ring at (lx, ly)
  answers?: string[] // when set, what counts as its answer instead of its name, e.g. a monument's city
  hint?: string // in a quiz with no map: the clue that asks for it, e.g. "Capital city"
  section?: string // and the part of the quiz it is in
}

// public/mp-map.json (tools/build_map.py)
export interface MapDistrict extends MapRegion {
  div: string // its division's name
}
export interface MapDivision extends MapRegion {
  n: number // number of districts in it
}
export interface MapData {
  w: number
  h: number
  state: string // outline path of the whole state
  divisions: MapDivision[] // 10
  districts: MapDistrict[] // 55
  credit: string
}

// public/india-map.json (tools/build_india_map.py)
export interface IndiaRegion extends MapRegion {
  kind: 'state' | 'ut'
}
export interface GridLine {
  label: string // e.g. "20°N"
  d: string // absolute SVG path
  x: number // where the label goes, on the map's left or bottom edge
  y: number
}
export interface IndiaMapData {
  w: number
  h: number
  outline: string // outline path of the whole country
  regions: IndiaRegion[] // 28 states and 8 union territories
  graticule: GridLine[] // latitude and longitude lines, every 5 degrees
  credit: string
}

// public/rivers-map.json (tools/build_rivers_map.py), drawn in india-map.json's coordinates
export interface RiverLine extends MapRegion {
  major: boolean // also asked in the Major rivers level
}
export interface RiversMapData {
  w: number
  h: number
  rivers: RiverLine[] // d is an open line; (lx, ly) is a point on it, clear of other rivers
  credit: string
}

// public/monuments-map.json (tools/build_monuments_map.py), in india-map.json's coordinates
export interface Monument {
  name: string
  alt: string[] // other names, e.g. "lal qila" for the Red Fort
  city: string
  cityAlt: string[] // other names of the city, e.g. "bombay"
  state: string // a state or union territory, as india-map.json names it
  lx: number // where it is on the map
  ly: number
}
export interface MonumentsMapData {
  w: number
  h: number
  monuments: Monument[]
  credit: string
}

// public/dams-map.json (tools/build_dams_map.py), in india-map.json's coordinates
export interface Dam {
  name: string // "Tehri Dam"
  alt: string[] // other names, e.g. "tehri"
  short?: string // a shorter label for the map, e.g. "Tehri"
  river: string // the river it holds back
  state: string // a state or union territory, as india-map.json names it
  major: boolean // also asked in the Major dams level
  lx: number // where it is on the map
  ly: number
}
export interface DamsMapData {
  w: number
  h: number
  dams: Dam[]
  credit: string
}

// Game state, driven by the pure reducer in engine.ts.

/**
 * click: the game names a place, you click it. type: you type names in any order. name: the game
 * lights up one place at a time and you type its name.
 */
export type Mode = 'click' | 'type' | 'name'
export type Phase = 'ready' | 'playing' | 'paused' | 'finished'
export type EndReason = 'all' | 'time' | 'gaveUp'

/** What the engine needs to know about the regions being quizzed. */
export interface Quiz {
  regions: MapRegion[]
  seconds: number // time limit
  one: string // what one region is called, e.g. "district" or "state or UT"
  many: string // and several, e.g. "districts" or "states and UTs"
}

export interface GameEvent {
  kind: 'correct' | 'wrong' | 'skipped'
  name: string
  clicked?: string
}

/**
 * The rest of a longer spelling that begins with an answer just taken. Typed on, it either finishes
 * that same answer ("agar" + "malwa"), or names another one it begins ("indian" + "ocean").
 */
export interface Tail {
  rest: string // what is left to type: "malwa"
  spelling: string // the whole spelling it ends: "agarmalwa"
  place: string | null // the other place that spelling names; null if it is the one just taken
}

export interface GameState {
  quiz: Quiz
  mode: Mode
  phase: Phase
  queue: string[] // unresolved names; in click and name modes in ask order, queue[0] is current
  found: string[] // in answer order
  missed: string[] // filled when the round ends: everything still unanswered
  flash: string | null // region last clicked wrongly (cleared by 'clearFlash')
  typed: string
  tails: Tail[] // what may still be typed after an answer taken at a shorter spelling
  secondsLeft: number
  showMarkers: boolean
  endReason: EndReason | null
  lastEvent: GameEvent | null
}

export type Action =
  | { type: 'start'; quiz: Quiz; mode: Mode; order: string[] } // order = shuffle(names, Math.random) done by the caller
  | { type: 'play' } // the Play game button: starts the clock
  | { type: 'click'; name: string }
  | { type: 'type'; text: string }
  | { type: 'skip' }
  | { type: 'tick' }
  | { type: 'pause' }
  | { type: 'resume' }
  | { type: 'giveUp' }
  | { type: 'clearFlash' }
  | { type: 'toggleMarkers' }
